{"code": "const [led, q1, q2] = await Promise.all([
  tools.grep({ pattern: "ind-topolog|final topology|final-topology", path: "AUDIT_LEDGER.md" }),
  tools.grep({ pattern: "final topology|coinduced|IndTopology", path: "coord" }),
  tools.grep({ pattern: "IsTopologicalRing|topological field|TopologicalField", path: "LeanFormal/IUT/Foundations" }),
]);
console.log("ledger:", JSON.stringify(led.matches.slice(0,50), null, 1));
console.log("coord:", JSON.stringify(q1.matches.slice(0,50), null, 1));
console.log("LF:", JSON.stringify(q2.matches.slice(0,50), null, 1));
", "description": "Search ledger and coord for final topology notes"}

